patches.new:
if limite_diario_alcanzado():
    # V130: el límite diario heredado deja de cancelar la cola
    # silenciosamente. Solo bloquea si el usuario activa de forma
    # explícita bloquear_al_llegar_limite_diario.
    cfg_limite = cargar_configuracion_general()
    if bool(cfg_limite.get("bloquear_al_llegar_limite_diario", False)):
        cola_cancelar = True
        ventana.after(
            0,
            lambda: estado.configure(
                text=(
                    "⏹ Límite diario alcanzado (bloqueo activado). "
                    "Los anuncios restantes quedan pendientes."
                )
            )
        )
        break
    else:
        try:
            ventana.after(
                0,
                lambda: estado.configure(
                    text="⚠️ Límite diario orientativo alcanzado · continuando la cola..."
                )
            )
        except Exception:
            pass
